{% stylesheet %}
  .free-shipping-wrapper { margin: 1rem 0; padding: 1rem; background: #f8f9fa; border-radius: 6px; }
  .shipping-message { font-size: 0.9rem; margin-bottom: 0.5rem; text-align: center; }
  .progress-track { height: 8px; background: #e0e0e0; border-radius: 4px; overflow: hidden; }
  .progress-fill { height: 100%; background: #000; transition: width 0.3s ease; }
{% endstylesheet %}
